-- Only two unadmitted candidate descriptions change. Historical AAUW and
-- Rotary source records, the first admitted five and all existing captures stay.
do $guard$
begin
 if encode(extensions.digest(convert_to(pg_get_functiondef('private.program_award_expansion_candidate(text)'::regprocedure),'UTF8'),'sha256'),'hex') <> '75e4534704b7ee60a452b7f1b95f7d7c9c8368cb79f2fed69b4b1f90c8227e35'
 then raise exception 'Unadmitted expansion candidate preimage changed.' using errcode='40001';end if;
 if exists(select 1 from public.program_award_expansion_admissions where cohort_key in ('aauw_international','cooke_transfer','rotary_peace'))
 or exists(select 1 from public.program_award_registry where cohort_key in ('aauw_international','cooke_transfer','rotary_peace'))
 then raise exception 'An affected candidate is already admitted; preserve its identity and history.' using errcode='40001';end if;
end;$guard$;

